record.field:
record.ensure_one()
job = record
kit = job.x_parts_kit_id
if not kit:
    raise UserError('Изберете комплект части.')
if kit not in job.x_machine_id.x_parts_kit_ids:
    raise UserError('Избраният комплект не е зададен за тази машина.')
if job.x_state == 'cancel':
    raise UserError('Отказана заявка не може да добавя части към оферта.')
order = job.x_sale_order_id
repair = job.x_repair_id
if order and order.state == 'cancel':
    raise UserError('Свързаната оферта е отказана.')
if not order:
    if repair:
        if not repair.sale_order_id:
            repair.action_create_sale_order()
        order = repair.sale_order_id
    else:
        order = env['sale.order'].with_company(job.x_company_id).with_context(mail_create_nosubscribe=True).create({
            'partner_id': job.x_partner_id.id,
            'company_id': job.x_company_id.id,
            'origin': '%s / %s' % (job.x_reference or job.x_name, job.x_machine_id.x_name),
        })
    job.write({'x_sale_order_id': order.id})
if env['sale.order.line'].search_count([
    ('order_id', '=', order.id),
    ('x_hm_job_id', '=', job.id),
    ('x_hm_parts_kit_id', '=', kit.id),
]):
    raise UserError('Този комплект вече е добавен към сервизната оферта.')
if not kit.x_line_ids:
    raise UserError('Комплектът няма въведени части.')
for line in kit.x_line_ids:
    env['sale.order.line'].create({
        'order_id': order.id,
        'product_id': line.x_product_id.id,
        'product_uom_qty': line.x_qty or 1.0,
        'x_hm_parts_kit_id': kit.id,
        'x_hm_job_id': job.id,
    })
action = {'type': 'ir.actions.act_window', 'res_model': 'sale.order', 'view_mode': 'form', 'res_id': order.id, 'target': 'current'}
